type FixtureInput441 = Omit<(typeof literals441)[number]['input'], 'recordCorrespondence'> & {
  recordCorrespondence: Array<(typeof literals441)[number]['input']['recordCorrespondence'][number]>
}
function fixture441(input: FixtureInput441 = literals441[0]!.input, filename = ':memory:') {
  const trace: string[] = []
  const sqlite = new Database(filename, { timeout: 0, verbose(sql) { if (typeof sql !== 'string') throw new TypeError('Expected SQL trace text'); trace.push(sql) } })
  try {
    sqlite.pragma('foreign_keys=ON')
    const db = drizzle(sqlite, { schema }); identityFunctions(db)
    migrate(db, { migrationsFolder: 'db/migrations' })
    db.insert(schema.title).values([...TITLE_SEED]).run()
    db.insert(schema.enterprise).values(input.enterprise as never).run()
    db.insert(schema.record).values(input.record as never).run()
    db.insert(schema.recordEvent).values(input.recordEvent as never).run()
    if (input.platformQuery.length) db.insert(schema.platformQuery).values(input.platformQuery as never).run()
    if (input.platformRelation.length) db.insert(schema.platformRelation).values(input.platformRelation as never).run()
    if (input.platformBusinessRecord.length) db.insert(schema.platformBusinessRecord).values(input.platformBusinessRecord as never).run()
    if (input.platformBusinessRecordVersion.length) db.insert(schema.platformBusinessRecordVersion).values(input.platformBusinessRecordVersion as never).run()
    if (input.platformBusinessObservation.length) db.insert(schema.platformBusinessObservation).values(input.platformBusinessObservation as never).run()
    if (input.recordCorrespondence.length) db.insert(schema.recordCorrespondence).values(input.recordCorrespondence as never).run()
    // FK checks do not validate business interface; assert the seeded rows independently below.
    expect(sqlite.pragma('foreign_key_check'), 'seed FK guard').toEqual([])
    const request = structuredClone(input.request)
    const batch = () => sqlite.transaction(() => readAnnualComparisonBatch(sqlite, db, request))()
    const adapter = () => sqlite.transaction(() => readPlatformComparisonProcesses(sqlite, request))()
    return { sqlite, db, request, batch, adapter, trace }
  } catch (error) { sqlite.close(); throw error }
}
type Fixture441 = ReturnType<typeof fixture441>
function readonly441<T>(f: Fixture441, action: () => T): T {
  f.sqlite.pragma('query_only=ON')
  const before = f.sqlite.prepare('select total_changes() n').get()
  const inTransaction = f.sqlite.inTransaction
  try { return action() } finally {
    expect(f.sqlite.prepare('select total_changes() n').get(), 'zero-write guard').toEqual(before)
    expect(f.sqlite.pragma('query_only', { simple: true })).toBe(1)
    expect(f.sqlite.inTransaction, 'transaction ownership').toBe(inTransaction)
  }
}
