function firstSeedGuard441(f: Fixture441) {
  expect(f.request).toEqual({ enterpriseId: 1, titleCode: 'little_giant', eventIds: [11], selectedQueryIds: [101] })
  expect(f.sqlite.prepare(`select e.id,r.enterprise_id owner,r.title_code title from record_event e join record r on r.id=e.record_id order by e.id`).all()).toEqual([
    { id: 11, owner: 1, title: 'little_giant' }, { id: 12, owner: 1, title: 'specialized_sme' },
  ])
  expect(f.sqlite.prepare(`select q.id,q.title_code title,q.rdjb,r.id relationId,r.relation_key key,o.record_id recordId,o.version_id versionId,b.interface
    from platform_query q join platform_relation r on r.query_id=q.id join platform_business_observation o on o.relation_id=r.id
    join platform_business_record b on b.id=o.record_id order by q.id`).all()).toEqual([
    { id:101,title:'little_giant',rdjb:'3',relationId:201,key:'甲·2024',recordId:1,versionId:1,interface:'business_list' },
    { id:102,title:'specialized_sme',rdjb:'2',relationId:202,key:'　业务／乙-2024　',recordId:2,versionId:2,interface:'business_list' },
    { id:103,title:'specialized_sme',rdjb:'2',relationId:203,key:'业务／乙-2024',recordId:2,versionId:3,interface:'business_list' },
  ])
  expect(f.sqlite.prepare(`select q.id,count(r.id) n,max(r.sequence_no) last,
    json_extract(q.collection_evidence,'$.pages[0].fetchedCount') fetched,
    json_extract(q.collection_evidence,'$.pages[0].declaredTotal') total
    from platform_query q left join platform_relation r on r.query_id=q.id group by q.id order by q.id`).all()).toEqual([
    {id:101,n:1,last:1,fetched:1,total:1},{id:102,n:1,last:1,fetched:1,total:1},{id:103,n:1,last:1,fetched:1,total:1},
  ])
  expect(f.sqlite.prepare('select count(*) n from record_correspondence').get()).toEqual({ n: 0 })
  defaultSourceGuard441(f)
  expect(readEventAnnualProcess(f.db,12)!.sourceRefs.observations.map(r=>r.relationId)).toEqual([202,203])
  const complete=f.sqlite.transaction(()=>readAnnualComparisonBatch(f.sqlite,f.db,{...f.request,selectedQueryIds:[101,102,103]}))()
  expect(complete.kind,'all-selected control admits original structural gates').toBe('present')
  expect(JSON.stringify(complete.entries[0]!.read.sourceRefs)).toBe(sourceGolden441.sourceBytes)
}
it('closure441_first_guarded_RED', () => {
  const f = fixture441()
  try { readonly441(f, () => {
    readonly441(f, () => firstSeedGuard441(f)) // Must all pass BEFORE comparison; no catch swallowing a fixture failure.
    let failure: unknown
    let out: ReturnType<Fixture441['batch']> | undefined
    try { out = f.batch() } catch (error) { failure = error }
    if (failure !== undefined) {
      expect(failure, 'only the intended business refusal is an acceptable RED diagnosis').toEqual(new Error('platform_comparison_scope_unavailable'))
    }
    // A failing default/seed/zero-write guard is NOT the intended RED receipt.
    expect(failure, 'independent other history must be admitted; baseline scope refusal is the intended RED').toBeUndefined()
    expect(out!.kind).toBe('present')
    expect(out!.entries[0]!.read.sourceRefs).toEqual(sourceGolden441.source)
  }) } finally { f.sqlite.close() }
})
for (const literal of literals441) it(literal.name, () => {
  const f = fixture441(literal.input)
  try { readonly441(f, () => {
    const requestBytes = JSON.stringify(f.request)
    const expected = literal.expected
    if ('error' in expected && expected.error) {
      expect(() => f.batch()).toThrowError(new Error(expected.error))
      expect(() => f.adapter()).toThrowError(new Error(expected.error))
    } else {
      const batch = f.batch(), processes = f.adapter()
      expect(batch.kind).toBe(expected.kind)
      if (expected.kind === 'absent') {
        expect(batch.entries).toEqual([]); expect([...batch.history]).toEqual([]); expect(processes).toEqual([])
        expect(batch.admission.kind).toBe('scope_closure')
        expect(batch.admission.expandedCharge).toBeNull()
        expect(batch.admission.sourceUpperBytes).toEqual([])
      } else {
        expect(batch.entries).toHaveLength(1); expect(processes).toHaveLength(1)
        const { input, read } = batch.entries[0]!
        expect(read.sourceRefs.titleScopeRefs).toEqual(expected.fullTitleScopeRefs)
        const fullExpected={...sourceGolden441.source,titleScopeRefs:expected.fullTitleScopeRefs}
        expect(JSON.stringify(read.sourceRefs)).toBe(JSON.stringify(fullExpected))
        expect(read.sourceGeneration).toBe(createHash('sha256').update(JSON.stringify(fullExpected)).digest('hex'))
        expect(input.coverage.map(q => q.queryId)).toEqual(expected.currentCoverageQueryIds)
        expect(read.sourceRefs.observations.map(r => r.relationId)).toEqual(expected.currentObservationRelationIds)
        expect([...batch.history].map(([id, rows]) => [id, [...rows].sort((a,b)=>a-b)]).sort((a,b)=>Number(a[0])-Number(b[0]))).toEqual(expected.fullHistory)
        expect(processes[0]!.currentDecisionRefs.map(d=>d.id)).toEqual(expected.currentDecisionIds)
        expect(processes[0]!.sourceRefs).toEqual(read.sourceRefs)
        expect(processes[0]!.sourceGeneration).toBe(read.sourceGeneration)
      }
    }
    expect(JSON.stringify(f.request), 'selected IDs are caller-owned and unchanged').toBe(requestBytes)
  }) } finally { f.sqlite.close() }
})
