it('closure_single_classification_trace', () => {
  const f=fixture441()
  const captures:{sql:string;method:string;params:unknown[]}[]=[]
  const original=f.sqlite.prepare.bind(f.sqlite)
  // Test-local observation of actual statements. No product/classifier debug export.
  f.sqlite.prepare=((sql:string)=>{
    const statement=original(sql)
    const proxy: typeof statement = new Proxy(statement, {get(target,key){
      const value=Reflect.get(target,key,target)
      if(['get','all','run'].includes(String(key)) && typeof value==='function')return (...params:unknown[])=>{
        captures.push({sql,method:String(key),params:structuredClone(params)})
        return value.apply(target,params)
      }
      return typeof value==='function' ? (...args:unknown[])=>{
        const result=value.apply(target,args)
        return result===target ? proxy : result
      } : value
    }})
    return proxy
  }) as typeof f.sqlite.prepare
  try { readonly441(f,()=>{
    captures.length=0
    expect(f.batch().kind).toBe('present')
    const sqlCalls=captures.slice()
    const hydration=sqlCalls.filter(x=>x.method==='all')
    // These predicates describe the proposed private SQL projections, to be reviewed
    // against final SQL before runtime. They do not count COUNT/SUM admission reads.
    const ids=hydration.filter(x=>/isPotential/i.test(x.sql)&&/limit\s+51\b/i.test(x.sql))
    const queries=hydration.filter(x=>/\bmetadata\b/.test(x.sql)&&/collection_evidence/.test(x.sql)&&/\bpages\b/.test(x.sql))
    const history=hydration.filter(x=>/\bversionRecordId\b/.test(x.sql))
    const decisions=hydration.filter(x=>/\bproofCount\b/.test(x.sql)&&/\bqueryTitle\b/.test(x.sql))
    const classificationM=hydration.filter(x=>/\bisAnnualRow\b/.test(x.sql)&&/\bcontentHash\b/.test(x.sql))
    for(const [label,values] of Object.entries({ids,queries,history,decisions,classificationM}))
      expect(values,label+' once').toHaveLength(1)
    expect(f.request.selectedQueryIds).toEqual([101])
    expect(queries[0]!.params, 'full dependency closure is bound').toContain('[101,102,103]')
    const titleHydration=hydration.filter(x=>/^select\s+"platform_relation"\."id",\s*"platform_relation"\."query_id",\s*"platform_relation"\."relation_key"/i.test(x.sql))
    expect(titleHydration,'original T hydration once').toHaveLength(1)
    // Groups owns one authoritative metadata reread for current observations.
    const originalM=hydration.filter(x=>/^select\s+"platform_relation"\."id",\s*"platform_business_observation"\."record_id"/i.test(x.sql))
    expect(originalM,'groups metadata only, no discarded preclassification reread').toHaveLength(1)
    expect(originalM[0]!.params).toEqual([201])
    const again=captures.length
    expect(f.batch().entries[0]!.read.sourceGeneration).toBe(sourceGolden441.sourceGeneration)
    expect(captures.slice(again).filter(x=>x.method==='all'&&/isPotential/i.test(x.sql)&&/limit\s+51\b/i.test(x.sql))).toHaveLength(1)
  }) } finally {f.sqlite.prepare=original as typeof f.sqlite.prepare;f.sqlite.close()}
})
