function noWritesRemaining441<T>(sqlite:Database.Database, action:()=>T):T {
  sqlite.pragma('query_only=ON')
  const before=sqlite.prepare('select total_changes() n').get(), owned=sqlite.inTransaction
  try{return action()}finally{
    expect(sqlite.prepare('select total_changes() n').get()).toEqual(before)
    expect(sqlite.pragma('query_only',{simple:true})).toBe(1)
    expect(sqlite.inTransaction).toBe(owned)
  }
}
